const std = @import("std");

pub const ActivationType = enum {
    relu,
    gelu,
    sigmoid,
    tanh,
    none,
};

pub const RSFLayer = struct {
    weights: []f32,
    bias: []f32,
    input_dim: usize,
    output_dim: usize,
    activation: ActivationType,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, input_dim: usize, output_dim: usize, activation: ActivationType) !RSFLayer {
        const weights = try allocator.alloc(f32, input_dim * output_dim);
        const bias = try allocator.alloc(f32, output_dim);
        var prng = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.timestamp())));
        const random = prng.random();
        for (weights) |*w| w.* = random.float(f32) * 0.02;
        for (bias) |*b| b.* = 0.0;
        return RSFLayer{
            .weights = weights,
            .bias = bias,
            .input_dim = input_dim,
            .output_dim = output_dim,
            .activation = activation,
            .allocator = allocator,
        };
    }

    pub fn forward(self: *const RSFLayer, input: []const f32, output: []f32) !void {
        for (0..self.output_dim) |j| {
            var sum: f32 = self.bias[j];
            for (0..self.input_dim) |i| {
                sum += input[i] * self.weights[i * self.output_dim + j];
            }
            output[j] = self.applyActivation(sum);
        }
    }

    pub fn inverse(self: *const RSFLayer, output: []const f32, input: []f32) !void {
        for (0..self.input_dim) |i| {
            var sum: f32 = 0.0;
            for (0..self.output_dim) |j| {
                const val = self.inverseActivation(output[j]) - self.bias[j];
                sum += val * self.weights[i * self.output_dim + j];
            }
            input[i] = sum;
        }
    }

    pub fn backward(self: *RSFLayer, grad_output: []const f32, grad_input: []f32) !void {
        for (0..self.input_dim) |i| {
            var sum: f32 = 0.0;
            for (0..self.output_dim) |j| {
                sum += grad_output[j] * self.weights[i * self.output_dim + j];
            }
            grad_input[i] = sum;
        }
    }

    fn applyActivation(self: *const RSFLayer, val: f32) f32 {
        return switch (self.activation) {
            .relu => if (val > 0) val else 0,
            .gelu => 0.5 * val * (1.0 + @as(f32, @floatCast(std.math.tanh(0.7978845608 * (val + 0.044715 * val * val * val))))),
            .sigmoid => 1.0 / (1.0 + @exp(-val)),
            .tanh => std.math.tanh(val),
            .none => val,
        };
    }

    fn inverseActivation(self: *const RSFLayer, val: f32) f32 {
        return switch (self.activation) {
            .relu => if (val > 0) val else 0,
            .gelu => val, 
            .sigmoid => -@log(1.0 / val - 1.0),
            .tanh => 0.5 * @log((1.0 + val) / (1.0 - val)),
            .none => val,
        };
    }

    pub fn deinit(self: *RSFLayer) void {
        self.allocator.free(self.weights);
        self.allocator.free(self.bias);
    }
};
