const std = @import("std");

pub const SFDOptimizer = struct {
    lr: f32,
    fisher_weight: f32,
    beta1: f32,
    beta2: f32,
    epsilon: f32,
    m: []f32,
    v: []f32,
    fisher_diag: []f32,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, size: usize, lr: f32) !SFDOptimizer {
        const m = try allocator.alloc(f32, size);
        @memset(m, 0);
        const v = try allocator.alloc(f32, size);
        @memset(v, 0);
        const fisher = try allocator.alloc(f32, size);
        @memset(fisher, 1.0);
        return SFDOptimizer{
            .lr = lr,
            .fisher_weight = 0.99,
            .beta1 = 0.9,
            .beta2 = 0.999,
            .epsilon = 1e-8,
            .m = m,
            .v = v,
            .fisher_diag = fisher,
            .allocator = allocator,
        };
    }

    pub fn update(self: *SFDOptimizer, weights: []f32, gradients: []const f32, step: u32) void {
        const t = @as(f32, @floatFromInt(step));
        const beta1_t = std.math.pow(f32, self.beta1, t);
        const beta2_t = std.math.pow(f32, self.beta2, t);
        for (weights, 0..) |*w, i| {
            const g = gradients[i];
            self.fisher_diag[i] = self.fisher_weight * self.fisher_diag[i] + (1.0 - self.fisher_weight) * g * g;
            self.m[i] = self.beta1 * self.m[i] + (1.0 - self.beta1) * g;
            self.v[i] = self.beta2 * self.v[i] + (1.0 - self.beta2) * g * g;
            const m_hat = self.m[i] / (1.0 - beta1_t);
            const v_hat = self.v[i] / (1.0 - beta2_t);
            const fisher_inv = 1.0 / (@sqrt(self.fisher_diag[i]) + self.epsilon);
            w.* -= self.lr * m_hat * fisher_inv / (@sqrt(v_hat) + self.epsilon);
        }
    }

    pub fn deinit(self: *SFDOptimizer) void {
        self.allocator.free(self.m);
        self.allocator.free(self.v);
        self.allocator.free(self.fisher_diag);
    }
};
