const std = @import("std");

pub const MGTTokenizer = struct {
    vocab: std.StringArrayHashMap(u32),
    inv_vocab: std.AutoArrayHashMap(u32, []const u8),
    use_morphology: bool,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !MGTTokenizer {
        var vocab = std.StringArrayHashMap(u32).init(allocator);
        try vocab.ensureTotalCapacity(capacity);
        var inv_vocab = std.AutoArrayHashMap(u32, []const u8).init(allocator);
        try inv_vocab.ensureTotalCapacity(capacity);
        return MGTTokenizer{
            .vocab = vocab,
            .inv_vocab = inv_vocab,
            .use_morphology = true,
            .allocator = allocator,
        };
    }

    pub fn encode(self: *MGTTokenizer, text: []const u8, max_len: usize) ![]u32 {
        var tokens = std.ArrayList(u32).init(self.allocator);
        errdefer tokens.deinit();
        var it = std.mem.tokenize(u8, text, " ");
        while (it.next()) |word| {
            if (tokens.items.len >= max_len) break;
            if (self.use_morphology) {
                try self.decomposeMorphological(word, &tokens);
            } else {
                const id = self.vocab.get(word) orelse 0;
                try tokens.append(id);
            }
        }
        return tokens.toOwnedSlice();
    }

    fn decomposeMorphological(self: *MGTTokenizer, word: []const u8, tokens: *std.ArrayList(u32)) !void {
        if (word.len > 4) {
            const prefix = word[0..2];
            const root = word[2..];
            try tokens.append(self.vocab.get(prefix) orelse 0);
            try tokens.append(self.vocab.get(root) orelse 0);
        } else {
            try tokens.append(self.vocab.get(word) orelse 0);
        }
    }

    pub fn decode(self: *MGTTokenizer, tokens: []const u32) ![]u8 {
        var out = std.ArrayList(u8).init(self.allocator);
        errdefer out.deinit();
        for (tokens) |id| {
            if (self.inv_vocab.get(id)) |word| {
                try out.appendSlice(word);
                try out.append(' ');
            }
        }
        return out.toOwnedSlice();
    }

    pub fn deinit(self: *MGTTokenizer) void {
        self.vocab.deinit();
        self.inv_vocab.deinit();
    }
};
