const std = @import("std");
const fractal = @import("fractal_lpu.zig");
const rsf = @import("rsf.zig");
const sfd = @import("sfd.zig");
const mgt = @import("mgt.zig");

pub const JaideEngine = struct {
    hierarchy: fractal.FractalTileHierarchy,
    layers: []rsf.RSFLayer,
    optimizer: sfd.SFDOptimizer,
    tokenizer: mgt.MGTTokenizer,
    allocator: std.mem.Allocator,
    step: u32,

    pub fn init(allocator: std.mem.Allocator, config: struct {
        depth: usize,
        width: usize,
        vocab_size: usize,
        fractal_levels: u8,
    }) !*JaideEngine {
        var self = try allocator.create(JaideEngine);
        self.allocator = allocator;
        self.hierarchy = try fractal.FractalTileHierarchy.init(allocator, config.fractal_levels, 1024, 8);
        self.layers = try allocator.alloc(rsf.RSFLayer, config.depth);
        for (self.layers) |*layer| {
            layer.* = try rsf.RSFLayer.init(allocator, config.width, config.width, .relu);
        }
        self.optimizer = try sfd.SFDOptimizer.init(allocator, config.depth * config.width * config.width, 1e-4);
        self.tokenizer = try mgt.MGTTokenizer.init(allocator, config.vocab_size);
        self.step = 0;
        return self;
    }

    pub fn process(self: *JaideEngine, input_text: []const u8) ![]u8 {
        const tokens = try self.tokenizer.encode(input_text, 1024);
        defer self.allocator.free(tokens);
        var data = try self.allocator.alloc(f32, self.layers[0].input_dim);
        defer self.allocator.free(data);
        @memset(data, 0.0);
        for (tokens, 0..) |t, i| {
            if (i < data.len) data[i] = @as(f32, @floatFromInt(t));
        }
        var current = data;
        var next_data = try self.allocator.alloc(f32, data.len);
        defer self.allocator.free(next_data);
        for (self.layers, 0..) |*layer, i| {
            try self.hierarchy.mapNodeToTile(@as(u32, @intCast(i)), @as(u32, @intCast(i % 8)));
            try layer.forward(current, next_data);
            @memcpy(current, next_data);
        }
        const out_tokens = try self.allocator.alloc(u32, tokens.len);
        defer self.allocator.free(out_tokens);
        for (current, 0..) |val, i| {
            if (i < out_tokens.len) out_tokens[i] = @as(u32, @intFromFloat(val));
        }
        return try self.tokenizer.decode(out_tokens);
    }

    pub fn deinit(self: *JaideEngine) void {
        self.hierarchy.deinit();
        for (self.layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
        self.optimizer.deinit();
        self.tokenizer.deinit();
        self.allocator.destroy(self);
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    const jaide = try JaideEngine.init(allocator, .{
        .depth = 12,
        .width = 512,
        .vocab_size = 50000,
        .fractal_levels = 3,
    });
    defer jaide.deinit();
    const result = try jaide.process("Jaide architectural root level initialization sequence.");
    defer allocator.free(result);
    std.debug.print("{s}\n", .{result});
}
