const std = @import("std");

pub const FractalDimension = enum(u8) {
    Dimension1 = 1,
    Dimension2 = 2,
    Dimension3 = 3,
};

pub const ComputeUnit = struct {
    identifier: u32,
    weight: i32,
    load: u32,
    status: enum { idle, busy, fault },
};

pub const FractalTile = struct {
    identifier: u32,
    dimension: FractalDimension,
    units: []ComputeUnit,
    sub_tiles: ?[]*FractalTile,
    parent: ?*FractalTile,

    pub fn init(allocator: std.mem.Allocator, identifier: u32, dimension: FractalDimension, number_of_units: usize) !*FractalTile {
        var tile = try allocator.create(FractalTile);
        tile.identifier = identifier;
        tile.dimension = dimension;
        tile.units = try allocator.alloc(ComputeUnit, number_of_units);
        var index: usize = 0;
        while (index < number_of_units) : (index += 1) {
            tile.units[index] = .{
                .identifier = @as(u32, @intCast(index)),
                .weight = 1,
                .load = 0,
                .status = .idle,
            };
        }
        tile.sub_tiles = null;
        tile.parent = null;
        return tile;
    }

    pub fn deinit(self: *FractalTile, allocator: std.mem.Allocator) void {
        if (self.sub_tiles) |subs| {
            for (subs) |sub| {
                sub.deinit(allocator);
            }
            allocator.free(subs);
        }
        allocator.free(self.units);
        allocator.destroy(self);
    }
};

pub const FractalTileHierarchy = struct {
    root_tile: *FractalTile,
    hierarchy_allocator: std.mem.Allocator,
    configuration: struct {
        hierarchy_levels: u8,
        units_per_tile: usize,
        number_of_tiles: u32,
    },

    pub fn init(allocator: std.mem.Allocator, levels: u8, units_per_tile: usize, num_tiles: u32) !FractalTileHierarchy {
        const root = try FractalTile.init(allocator, 0, .Dimension3, units_per_tile);
        var self = FractalTileHierarchy{
            .root_tile = root,
            .hierarchy_allocator = allocator,
            .configuration = .{
                .hierarchy_levels = levels,
                .units_per_tile = units_per_tile,
                .number_of_tiles = num_tiles,
            },
        };
        try self.build_recursive_hierarchy(root, levels - 1);
        return self;
    }

    fn build_recursive_hierarchy(self: *FractalTileHierarchy, parent_tile: *FractalTile, remaining_levels: u8) !void {
        if (remaining_levels == 0) return;
        const number_of_sub_tiles = self.configuration.number_of_tiles;
        var sub_tiles_array = try self.hierarchy_allocator.alloc(*FractalTile, number_of_sub_tiles);
        var index: usize = 0;
        while (index < number_of_sub_tiles) : (index += 1) {
            sub_tiles_array[index] = try FractalTile.init(self.hierarchy_allocator, @as(u32, @intCast(index)), .Dimension2, self.configuration.units_per_tile);
            sub_tiles_array[index].parent = parent_tile;
            try self.build_recursive_hierarchy(sub_tiles_array[index], remaining_levels - 1);
        }
        parent_tile.sub_tiles = sub_tiles_array;
    }

    pub fn map_compute_node_to_tile(self: *FractalTileHierarchy, node_identifier: u32, tile_identifier: u32) !void {
        _ = self;
        _ = node_identifier;
        _ = tile_identifier;
    }

    pub fn execute_load_balancing(self: *FractalTileHierarchy) !void {
        _ = self;
    }

    pub fn deinit(self: *FractalTileHierarchy) void {
        self.root_tile.deinit(self.hierarchy_allocator);
    }
};
