const std = @import("std");

pub const ActivationType = enum {
    RectifiedLinearUnit,
    GaussianErrorLinearUnit,
    SigmoidUnit,
    HyperbolicTangentUnit,
    IdentityUnit,
};

pub const ReversibleSkipFlowLayer = struct {
    weight_matrix: []f32,
    bias_vector: []f32,
    input_dimension: usize,
    output_dimension: usize,
    activation_function: ActivationType,
    layer_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, input_dim: usize, output_dim: usize, activation: ActivationType) !ReversibleSkipFlowLayer {
        const weight_count = input_dim * output_dim;
        const weights = try allocator.alloc(f32, weight_count);
        const bias = try allocator.alloc(f32, output_dim);
        var pseudo_random_generator = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.nanoTimestamp())));
        const random_source = pseudo_random_generator.random();
        var i: usize = 0;
        while (i < weight_count) : (i += 1) {
            weights[i] = random_source.float(f32) * 0.02;
        }
        var j: usize = 0;
        while (j < output_dim) : (j += 1) {
            bias[j] = 0.0;
        }
        return ReversibleSkipFlowLayer{
            .weight_matrix = weights,
            .bias_vector = bias,
            .input_dimension = input_dim,
            .output_dimension = output_dim,
            .activation_function = activation,
            .layer_allocator = allocator,
        };
    }

    pub fn forward_propagation(self: *const ReversibleSkipFlowLayer, input_data: []const f32, output_buffer: []f32) !void {
        var j: usize = 0;
        while (j < self.output_dimension) : (j += 1) {
            var sum: f32 = self.bias_vector[j];
            var i: usize = 0;
            while (i < self.input_dimension) : (i += 1) {
                sum += input_data[i] * self.weight_matrix[i * self.output_dimension + j];
            }
            output_buffer[j] = self.apply_activation_logic(sum);
        }
    }

    pub fn inverse_propagation(self: *const ReversibleSkipFlowLayer, output_data: []const f32, input_buffer: []f32) !void {
        var i: usize = 0;
        while (i < self.input_dimension) : (i += 1) {
            var sum: f32 = 0.0;
            var j: usize = 0;
            while (j < self.output_dimension) : (j += 1) {
                const activation_inverse = self.apply_inverse_activation_logic(output_data[j]) - self.bias_vector[j];
                sum += activation_inverse * self.weight_matrix[i * self.output_dimension + j];
            }
            input_buffer[i] = sum;
        }
    }

    pub fn backward_propagation(self: *ReversibleSkipFlowLayer, gradient_output: []const f32, gradient_input: []f32) !void {
        var i: usize = 0;
        while (i < self.input_dimension) : (i += 1) {
            var sum: f32 = 0.0;
            var j: usize = 0;
            while (j < self.output_dimension) : (j += 1) {
                sum += gradient_output[j] * self.weight_matrix[i * self.output_dimension + j];
            }
            gradient_input[i] = sum;
        }
    }

    fn apply_activation_logic(self: *const ReversibleSkipFlowLayer, value: f32) f32 {
        return switch (self.activation_function) {
            .RectifiedLinearUnit => if (value > 0.0) value else 0.0,
            .GaussianErrorLinearUnit => 0.5 * value * (1.0 + @as(f32, @floatCast(std.math.tanh(0.7978845608 * (value + 0.044715 * value * value * value))))),
            .SigmoidUnit => 1.0 / (1.0 + @exp(-value)),
            .HyperbolicTangentUnit => std.math.tanh(value),
            .IdentityUnit => value,
        };
    }

    fn apply_inverse_activation_logic(self: *const ReversibleSkipFlowLayer, value: f32) f32 {
        return switch (self.activation_function) {
            .RectifiedLinearUnit => if (value > 0.0) value else 0.0,
            .GaussianErrorLinearUnit => value,
            .SigmoidUnit => -@log(1.0 / (value + 1e-12) - 1.0),
            .HyperbolicTangentUnit => 0.5 * @log((1.0 + value) / (1.0 - value + 1e-12)),
            .IdentityUnit => value,
        };
    }

    pub fn deinit(self: *ReversibleSkipFlowLayer) void {
        self.layer_allocator.free(self.weight_matrix);
        self.layer_allocator.free(self.bias_vector);
    }
};
