const std = @import("std");

pub const SpectralFisherDiagonalOptimizer = struct {
    learning_rate: f32,
    fisher_decay: f32,
    beta_first: f32,
    beta_second: f32,
    epsilon_constant: f32,
    first_moment_vector: []f32,
    second_moment_vector: []f32,
    fisher_diagonal_estimate: []f32,
    optimizer_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, parameter_size: usize, initial_learning_rate: f32) !SpectralFisherDiagonalOptimizer {
        const first_moments = try allocator.alloc(f32, parameter_size);
        @memset(first_moments, 0.0);
        const second_moments = try allocator.alloc(f32, parameter_size);
        @memset(second_moments, 0.0);
        const fisher_estimate = try allocator.alloc(f32, parameter_size);
        @memset(fisher_estimate, 1.0);
        return SpectralFisherDiagonalOptimizer{
            .learning_rate = initial_learning_rate,
            .fisher_decay = 0.99,
            .beta_first = 0.9,
            .beta_second = 0.999,
            .epsilon_constant = 1e-8,
            .first_moment_vector = first_moments,
            .second_moment_vector = second_moments,
            .fisher_diagonal_estimate = fisher_estimate,
            .optimizer_allocator = allocator,
        };
    }

    pub fn apply_parameter_update(self: *SpectralFisherDiagonalOptimizer, weight_slice: []f32, gradient_slice: []const f32, current_step: u32) void {
        const time_step = @as(f32, @floatFromInt(current_step));
        const bias_correction_first = 1.0 - std.math.pow(f32, self.beta_first, time_step);
        const bias_correction_second = 1.0 - std.math.pow(f32, self.beta_second, time_step);
        var index: usize = 0;
        while (index < weight_slice.len) : (index += 1) {
            const gradient_value = gradient_slice[index];
            self.fisher_diagonal_estimate[index] = self.fisher_decay * self.fisher_diagonal_estimate[index] + (1.0 - self.fisher_decay) * gradient_value * gradient_value;
            self.first_moment_vector[index] = self.beta_first * self.first_moment_vector[index] + (1.0 - self.beta_first) * gradient_value;
            self.second_moment_vector[index] = self.beta_second * self.second_moment_vector[index] + (1.0 - self.beta_second) * gradient_value * gradient_value;
            const corrected_first_moment = self.first_moment_vector[index] / bias_correction_first;
            const corrected_second_moment = self.second_moment_vector[index] / bias_correction_second;
            const fisher_inverse_scaling = 1.0 / (@sqrt(self.fisher_diagonal_estimate[index]) + self.epsilon_constant);
            weight_slice[index] -= self.learning_rate * corrected_first_moment * fisher_inverse_scaling / (@sqrt(corrected_second_moment) + self.epsilon_constant);
        }
    }

    pub fn deinit(self: *SpectralFisherDiagonalOptimizer) void {
        self.optimizer_allocator.free(self.first_moment_vector);
        self.optimizer_allocator.free(self.second_moment_vector);
        self.optimizer_allocator.free(self.fisher_diagonal_estimate);
    }
};
