const std = @import("std");

pub const MorphologicalGrammaticalTokenizer = struct {
    vocabulary_mapping: std.StringArrayHashMap(u32),
    inverse_vocabulary_mapping: std.AutoArrayHashMap(u32, []const u8),
    enable_morphology_processing: bool,
    tokenizer_allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, maximum_vocabulary_capacity: usize) !MorphologicalGrammaticalTokenizer {
        var vocabulary = std.StringArrayHashMap(u32).init(allocator);
        try vocabulary.ensureTotalCapacity(maximum_vocabulary_capacity);
        var inverse_vocabulary = std.AutoArrayHashMap(u32, []const u8).init(allocator);
        try inverse_vocabulary.ensureTotalCapacity(maximum_vocabulary_capacity);
        return MorphologicalGrammaticalTokenizer{
            .vocabulary_mapping = vocabulary,
            .inverse_vocabulary_mapping = inverse_vocabulary,
            .enable_morphology_processing = true,
            .tokenizer_allocator = allocator,
        };
    }

    pub fn encode_string_to_tokens(self: *MorphologicalGrammaticalTokenizer, input_text: []const u8, maximum_token_length: usize) ![]u32 {
        var token_buffer = std.ArrayList(u32).init(self.tokenizer_allocator);
        errdefer token_buffer.deinit();
        var word_iterator = std.mem.tokenize(u8, input_text, " \n\r\t");
        while (word_iterator.next()) |word_segment| {
            if (token_buffer.items.len >= maximum_token_length) break;
            if (self.enable_morphology_processing) {
                try self.execute_morphological_decomposition(word_segment, &token_buffer);
            } else {
                const token_id = self.vocabulary_mapping.get(word_segment) orelse 0;
                try token_buffer.append(token_id);
            }
        }
        return token_buffer.toOwnedSlice();
    }

    fn execute_morphological_decomposition(self: *MorphologicalGrammaticalTokenizer, word_segment: []const u8, tokens: *std.ArrayList(u32)) !void {
        if (word_segment.len > 4) {
            const prefix_segment = word_segment[0..2];
            const root_segment = word_segment[2..];
            try tokens.append(self.vocabulary_mapping.get(prefix_segment) orelse 0);
            try tokens.append(self.vocabulary_mapping.get(root_segment) orelse 0);
        } else {
            try tokens.append(self.vocabulary_mapping.get(word_segment) orelse 0);
        }
    }

    pub fn decode_tokens_to_string(self: *MorphologicalGrammaticalTokenizer, tokens_array: []const u32) ![]u8 {
        var string_builder = std.ArrayList(u8).init(self.tokenizer_allocator);
        errdefer string_builder.deinit();
        for (tokens_array) |token_id| {
            if (self.inverse_vocabulary_mapping.get(token_id)) |decoded_word| {
                try string_builder.appendSlice(decoded_word);
                try string_builder.append(' ');
            }
        }
        return string_builder.toOwnedSlice();
    }

    pub fn deinit(self: *MorphologicalGrammaticalTokenizer) void {
        self.vocabulary_mapping.deinit();
        self.inverse_vocabulary_mapping.deinit();
    }
};
