const std = @import("std");

pub const NeuralActivationFunctionType = enum {
    RectifiedLinearActivation,
    GaussianErrorLinearActivation,
    LogisticSigmoidActivation,
    HyperbolicTangentActivation,
    LinearIdentityActivation,
};

pub const ReversibleSkipFlowNeuralLayer = struct {
    weight_parameter_matrix: []f32,
    bias_parameter_vector: []f32,
    input_tensor_dimension: usize,
    output_tensor_dimension: usize,
    activation_type_specification: NeuralActivationFunctionType,
    layer_memory_allocator: std.mem.Allocator,

    pub fn initialize_neural_layer(allocator_reference: std.mem.Allocator, input_dim: usize, output_dim: usize, activation: NeuralActivationFunctionType) !ReversibleSkipFlowNeuralLayer {
        const total_weight_count = input_dim * output_dim;
        const weights_slice = try allocator_reference.alloc(f32, total_weight_count);
        const bias_slice = try allocator_reference.alloc(f32, output_dim);
        var random_number_generator = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.nanoTimestamp())));
        const random_instance = random_number_generator.random();
        var weight_iteration_index: usize = 0;
        while (weight_iteration_index < total_weight_count) : (weight_iteration_index += 1) {
            weights_slice[weight_iteration_index] = random_instance.float(f32) * 0.02;
        }
        var bias_iteration_index: usize = 0;
        while (bias_iteration_index < output_dim) : (bias_iteration_index += 1) {
            bias_slice[bias_iteration_index] = 0.0;
        }
        return ReversibleSkipFlowNeuralLayer{
            .weight_parameter_matrix = weights_slice,
            .bias_parameter_vector = bias_slice,
            .input_tensor_dimension = input_dim,
            .output_tensor_dimension = output_dim,
            .activation_type_specification = activation,
            .layer_memory_allocator = allocator_reference,
        };
    }

    pub fn execute_forward_pass_transformation(self_pointer: *const ReversibleSkipFlowNeuralLayer, input_tensor_data: []const f32, output_tensor_buffer: []f32) !void {
        var output_iteration_index: usize = 0;
        while (output_iteration_index < self_pointer.output_tensor_dimension) : (output_iteration_index += 1) {
            var accumulated_sum_value: f32 = self_pointer.bias_parameter_vector[output_iteration_index];
            var input_iteration_index: usize = 0;
            while (input_iteration_index < self_pointer.input_tensor_dimension) : (input_iteration_index += 1) {
                accumulated_sum_value += input_tensor_data[input_iteration_index] * self_pointer.weight_parameter_matrix[input_iteration_index * self_pointer.output_tensor_dimension + output_iteration_index];
            }
            output_tensor_buffer[output_iteration_index] = self_pointer.compute_activation_value(accumulated_sum_value);
        }
    }

    pub fn execute_inverse_pass_transformation(self_pointer: *const ReversibleSkipFlowNeuralLayer, output_tensor_data: []const f32, input_tensor_buffer: []f32) !void {
        var input_iteration_index: usize = 0;
        while (input_iteration_index < self_pointer.input_tensor_dimension) : (input_iteration_index += 1) {
            var accumulated_inverse_sum: f32 = 0.0;
            var output_iteration_index: usize = 0;
            while (output_iteration_index < self_pointer.output_tensor_dimension) : (output_iteration_index += 1) {
                const inverse_activation_value = self_pointer.compute_inverse_activation_value(output_tensor_data[output_iteration_index]) - self_pointer.bias_parameter_vector[output_iteration_index];
                accumulated_inverse_sum += inverse_activation_value * self_pointer.weight_parameter_matrix[input_iteration_index * self_pointer.output_tensor_dimension + output_iteration_index];
            }
            input_tensor_buffer[input_iteration_index] = accumulated_inverse_sum;
        }
    }

    pub fn execute_backward_gradient_propagation(self_pointer: *ReversibleSkipFlowNeuralLayer, gradient_output_tensor: []const f32, gradient_input_buffer: []f32) !void {
        var input_iteration_index: usize = 0;
        while (input_iteration_index < self_pointer.input_tensor_dimension) : (input_iteration_index += 1) {
            var accumulated_gradient_sum: f32 = 0.0;
            var output_iteration_index: usize = 0;
            while (output_iteration_index < self_pointer.output_tensor_dimension) : (output_iteration_index += 1) {
                accumulated_gradient_sum += gradient_output_tensor[output_iteration_index] * self_pointer.weight_parameter_matrix[input_iteration_index * self_pointer.output_tensor_dimension + output_iteration_index];
            }
            gradient_input_buffer[input_iteration_index] = accumulated_gradient_sum;
        }
    }

    fn compute_activation_value(self_pointer: *const ReversibleSkipFlowNeuralLayer, linear_value: f32) f32 {
        return switch (self_pointer.activation_type_specification) {
            .RectifiedLinearActivation => if (linear_value > 0.0) linear_value else 0.0,
            .GaussianErrorLinearActivation => 0.5 * linear_value * (1.0 + @as(f32, @floatCast(std.math.tanh(0.7978845608 * (linear_value + 0.044715 * linear_value * linear_value * linear_value))))),
            .LogisticSigmoidActivation => 1.0 / (1.0 + @exp(-linear_value)),
            .HyperbolicTangentActivation => std.math.tanh(linear_value),
            .LinearIdentityActivation => linear_value,
        };
    }

    fn compute_inverse_activation_value(self_pointer: *const ReversibleSkipFlowNeuralLayer, activated_value: f32) f32 {
        return switch (self_pointer.activation_type_specification) {
            .RectifiedLinearActivation => if (activated_value > 0.0) activated_value else 0.0,
            .GaussianErrorLinearActivation => activated_value,
            .LogisticSigmoidActivation => -@log(1.0 / (activated_value + 1e-15) - 1.0),
            .HyperbolicTangentActivation => 0.5 * @log((1.0 + activated_value) / (1.0 - activated_value + 1e-15)),
            .LinearIdentityActivation => activated_value,
        };
    }

    pub fn deinitialize_neural_layer(self_pointer: *ReversibleSkipFlowNeuralLayer) void {
        self_pointer.layer_memory_allocator.free(self_pointer.weight_parameter_matrix);
        self_pointer.layer_memory_allocator.free(self_pointer.bias_parameter_vector);
    }
};
