const std = @import("std");

pub const SpectralFisherDiagonalOptimizationManager = struct {
    global_learning_rate: f32,
    fisher_information_decay_rate: f32,
    first_moment_exponential_decay: f32,
    second_moment_exponential_decay: f32,
    numerical_stability_epsilon: f32,
    first_moment_state_vector: []f32,
    second_moment_state_vector: []f32,
    fisher_diagonal_estimation_vector: []f32,
    optimizer_memory_allocator: std.mem.Allocator,

    pub fn initialize_optimizer_manager(allocator_reference: std.mem.Allocator, parameter_collection_size: usize, initial_rate: f32) !SpectralFisherDiagonalOptimizationManager {
        const first_moments = try allocator_reference.alloc(f32, parameter_collection_size);
        @memset(first_moments, 0.0);
        const second_moments = try allocator_reference.alloc(f32, parameter_collection_size);
        @memset(second_moments, 0.0);
        const fisher_estimates = try allocator_reference.alloc(f32, parameter_collection_size);
        @memset(fisher_estimates, 1.0);
        return SpectralFisherDiagonalOptimizationManager{
            .global_learning_rate = initial_rate,
            .fisher_information_decay_rate = 0.99,
            .first_moment_exponential_decay = 0.9,
            .second_moment_exponential_decay = 0.999,
            .numerical_stability_epsilon = 1e-8,
            .first_moment_state_vector = first_moments,
            .second_moment_state_vector = second_moments,
            .fisher_diagonal_estimation_vector = fisher_estimates,
            .optimizer_memory_allocator = allocator_reference,
        };
    }

    pub fn apply_stochastic_parameter_updates(self_pointer: *SpectralFisherDiagonalOptimizationManager, parameter_slice: []f32, gradient_slice: []const f32, current_iteration_step: u32) void {
        const step_floating_point = @as(f32, @floatFromInt(current_iteration_step));
        const bias_correction_factor_first = 1.0 - std.math.pow(f32, self_pointer.first_moment_exponential_decay, step_floating_point);
        const bias_correction_factor_second = 1.0 - std.math.pow(f32, self_pointer.second_moment_exponential_decay, step_floating_point);
        var parameter_iteration_index: usize = 0;
        while (parameter_iteration_index < parameter_slice.len) : (parameter_iteration_index += 1) {
            const current_gradient = gradient_slice[parameter_iteration_index];
            self_pointer.fisher_diagonal_estimation_vector[parameter_iteration_index] = self_pointer.fisher_information_decay_rate * self_pointer.fisher_diagonal_estimation_vector[parameter_iteration_index] + (1.0 - self_pointer.fisher_information_decay_rate) * current_gradient * current_gradient;
            self_pointer.first_moment_state_vector[parameter_iteration_index] = self_pointer.first_moment_exponential_decay * self_pointer.first_moment_state_vector[parameter_iteration_index] + (1.0 - self_pointer.first_moment_exponential_decay) * current_gradient;
            self_pointer.second_moment_state_vector[parameter_iteration_index] = self_pointer.second_moment_exponential_decay * self_pointer.second_moment_state_vector[parameter_iteration_index] + (1.0 - self_pointer.second_moment_exponential_decay) * current_gradient * current_gradient;
            const corrected_first_moment = self_pointer.first_moment_state_vector[parameter_iteration_index] / bias_correction_factor_first;
            const corrected_second_moment = self_pointer.second_moment_state_vector[parameter_iteration_index] / bias_correction_factor_second;
            const adaptive_fisher_scaling = 1.0 / (@sqrt(self_pointer.fisher_diagonal_estimation_vector[parameter_iteration_index]) + self_pointer.numerical_stability_epsilon);
            parameter_slice[parameter_iteration_index] -= self_pointer.global_learning_rate * corrected_first_moment * adaptive_fisher_scaling / (@sqrt(corrected_second_moment) + self_pointer.numerical_stability_epsilon);
        }
    }

    pub fn deinitialize_optimizer_manager(self_pointer: *SpectralFisherDiagonalOptimizationManager) void {
        self_pointer.optimizer_memory_allocator.free(self_pointer.first_moment_state_vector);
        self_pointer.optimizer_memory_allocator.free(self_pointer.second_moment_state_vector);
        self_pointer.optimizer_memory_allocator.free(self_pointer.fisher_diagonal_estimation_vector);
    }
};
