const std = @import("std");

pub const MorphologicalGrammaticalSegmentationTokenizer = struct {
    vocabulary_string_to_id_map: std.StringArrayHashMap(u32),
    vocabulary_id_to_string_map: std.AutoArrayHashMap(u32, []const u8),
    morphological_processing_active_flag: bool,
    tokenizer_memory_allocator: std.mem.Allocator,

    pub fn initialize_tokenizer_system(allocator_reference: std.mem.Allocator, max_capacity_specification: usize) !MorphologicalGrammaticalSegmentationTokenizer {
        var string_map = std.StringArrayHashMap(u32).init(allocator_reference);
        try string_map.ensureTotalCapacity(max_capacity_specification);
        var id_map = std.AutoArrayHashMap(u32, []const u8).init(allocator_reference);
        try id_map.ensureTotalCapacity(max_capacity_specification);
        return MorphologicalGrammaticalSegmentationTokenizer{
            .vocabulary_string_to_id_map = string_map,
            .vocabulary_id_to_string_map = id_map,
            .morphological_processing_active_flag = true,
            .tokenizer_memory_allocator = allocator_reference,
        };
    }

    pub fn transform_text_to_token_identifiers(self_pointer: *MorphologicalGrammaticalSegmentationTokenizer, source_text: []const u8, max_sequence_length: usize) ![]u32 {
        var token_identifier_list = std.ArrayList(u32).init(self_pointer.tokenizer_memory_allocator);
        errdefer token_identifier_list.deinit();
        var word_segment_iterator = std.mem.tokenize(u8, source_text, " \n\r\t\t.,!?;:");
        while (word_segment_iterator.next()) |current_word_segment| {
            if (token_identifier_list.items.len >= max_sequence_length) break;
            if (self_pointer.morphological_processing_active_flag) {
                try self_pointer.decompose_word_into_morphological_units(current_word_segment, &token_identifier_list);
            } else {
                const identifier_lookup_result = self_pointer.vocabulary_string_to_id_map.get(current_word_segment) orelse 0;
                try token_identifier_list.append(identifier_lookup_result);
            }
        }
        return token_identifier_list.toOwnedSlice();
    }

    fn decompose_word_into_morphological_units(self_pointer: *MorphologicalGrammaticalSegmentationTokenizer, word_segment: []const u8, tokens_buffer: *std.ArrayList(u32)) !void {
        if (word_segment.len > 5) {
            const prefix_substring = word_segment[0..3];
            const root_substring = word_segment[3..];
            try tokens_buffer.append(self_pointer.vocabulary_string_to_id_map.get(prefix_substring) orelse 0);
            try tokens_buffer.append(self_pointer.vocabulary_string_to_id_map.get(root_substring) orelse 0);
        } else {
            try tokens_buffer.append(self_pointer.vocabulary_string_to_id_map.get(word_segment) orelse 0);
        }
    }

    pub fn transform_token_identifiers_to_text(self_pointer: *MorphologicalGrammaticalSegmentationTokenizer, identifiers_slice: []const u32) ![]u8 {
        var text_reconstruction_buffer = std.ArrayList(u8).init(self_pointer.tokenizer_memory_allocator);
        errdefer text_reconstruction_buffer.deinit();
        for (identifiers_slice) |current_identifier| {
            if (self_pointer.vocabulary_id_to_string_map.get(current_identifier)) |decoded_string_segment| {
                try text_reconstruction_buffer.appendSlice(decoded_string_segment);
                try text_reconstruction_buffer.append(' ');
            }
        }
        return text_reconstruction_buffer.toOwnedSlice();
    }

    pub fn deinitialize_tokenizer_system(self_pointer: *MorphologicalGrammaticalSegmentationTokenizer) void {
        self_pointer.vocabulary_string_to_id_map.deinit();
        self_pointer.vocabulary_id_to_string_map.deinit();
    }
};
